-- Offline contracts only; native maps, obstacles and battles use native_maps_probe.
local cache={};function require(name)if not cache[name]then cache[name]=assert(loadfile('mod/SandboxOfElysium/'..name:gsub('%.','/')..'.lua'))()end;return cache[name]end
local M=require('sandbox.model');local C=require('sandbox.catalog');local R=require('sandbox.runtime');local U=require('sandbox.ui');local D=require('sandbox.diagnostics');local count=0
local function test(name,fn)fn();count=count+1;print('PASS '..name)end
local newer={[5]='Farm',[18]='Village',[70]='Hoburg Village',[98]='Oasis',[109]='Tent Village'}
local function catalog()local c={terrainById={},byId={[13]={id=13,name='Spearman'}},itemNames={},spellKeys={},mods={}};for i,name in pairs(M.terrainNames)do c.terrainById[i]={id=i,name=name}end;return c end
local function apiForCatalog(changed)return{get=function(k,i)if k=='terrainLastIndex'then return 109 elseif k:find('LastIndex',1,true)then return-1 elseif k=='terrainName'then return i==5 and changed or M.terrainNames[i]elseif k=='terrain'then return 0 end end,spellInfo=function()end,testFieldEditorCapabilities=function()return{spellRecords=1}end,testFieldTerrains=function()return{0,2,5,18,70,98,109,1,197,327,158}end}end

test('the original six loaded identities stay unchanged',function()local old={[0]='Plain',[2]='Forest',[12]='Mountains',[107]='Swamp',[115]='Jungle',[117]='Desert'};for id,name in pairs(old)do assert(M.terrainNames[id]==name)end end)
test('five new canonical terrains round-trip empty and named one-sided schema4 setups',function()local c=catalog();for id in pairs(newer)do for _,n in ipairs({0,1})do local s=M.new();s.terrain=id;if n==1 then local u=M.add(s,13,'Spearman',1,8,9);u.nativeName='Map Guard'end;local loaded,why=M.decode(M.encode(s,{}),c,{});assert(loaded,why);assert(loaded.terrain==id and #loaded.units==n);if n==1 then assert(loaded.units[1].nativeName=='Map Guard'and loaded.units[1].team==1)end end end end)
test('changed loaded terrain identity refuses saved map data',function()local c=catalog();local s=M.new();s.terrain=5;c.terrainById[5].name='Changed Farm';local ok,why=M.decode(M.encode(s,{}),c,{});assert(not ok and why:find('unavailable or changed',1,true))end)
test('catalogue never advertises unverified context IDs or mismatched identities',function()local c=C.read(apiForCatalog());for id in pairs(newer)do assert(c.testFieldTerrains[id])end;for _,id in ipairs({1,197,327,158})do assert(not c.testFieldTerrains[id]and not M.terrainNames[id])end;c=C.read(apiForCatalog('Changed Farm'));assert(not c.testFieldTerrains[5])end)
test('older native terrain support refuses a new preset before closing the current field',function()local closed=0;local api={testFieldTerrains=function()return{0,2,12,107,115,117}end,closeTestField=function()closed=closed+1 end};local r=R.new(api,catalog());r.current=M.new();r.open=true;local s=M.new();s.terrain=5;local ok,why=r:build(s);assert(not ok and why:find('Farm requires',1,true)and closed==0 and r.current.terrain==0 and r.open)end)
test('template catalogue preserves navigation and distinguishes verified from unavailable contexts',function()local api={get=function()return 0 end,readIni=function()end,wrap=function()return 1 end,observe=function()return 1 end};local ui=U.new(api);ui.setSearchFocus=function()end;ui.catalog={environment={templates={{name='farm',installed=true,storedWidth=160,storedHeight=20,verifiedContext=true},{name='palisaden',installed=true,storedWidth=160,storedHeight=20,verifiedContext=false}}}};local rows;ui.menu=function(_,title,r)rows=r;return 999 end;ui:templateCatalogue();local text='';local ids={};for _,r in ipairs(rows)do if r[1]then ids[r[1]]=true;text=text..tostring(r[2])end end;assert(ids[1]and ids[2]and ids[999]and text:find('Playable via verified presets only',1,true)and text:find('Unavailable:',1,true))end)
test('diagnostics include bounded observed context, normalize booleans and preserve unavailable reasons',function()local api={get=function()return 0 end,readIni=function()end,testFieldState=function()return{complete=true,units={},grid={},issues={}}end,testFieldEnvironmentState=function()return{version=1,nativeTemplate='farm',atSea=false,setupReturned=true,unknownExtra='excluded'}end};local d=D.new(api);local s=M.new();local r={open=true,live={}};local snap=d:snapshot(s,r);assert(snap.summary.environment_nativeTemplate=='farm'and snap.summary.environment_atSea==0 and snap.summary.environment_setupReturned==1 and not snap.summary.environment_unknownExtra);api.testFieldEnvironmentState=function()return nil,'not_owner'end;assert(d:snapshot(s,r).summary.environment_result=='not_owner')end)
print(count..' offline native-map contracts passed; no native field or combat simulated')
